&lt;p class=&quot;s4&quot;&gt;&lt;strong&gt;&lt;span class=&quot;s2&quot;&gt;Preferred Qualifications&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;div class=&quot;s7&quot;&gt;&lt;span class=&quot;s6&quot;&gt;•&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;s5&quot;&gt;Experience selling or partnering on competitive backup and recovery or cyber resilience solutions.&lt;/span&gt;&lt;/div&gt;
